function travelRow(t){var seg=arr(t.segments),house=arr(t.housing);return '<div class="v1682-row"><div><strong>'+esc(t.models&&t.models.display_name||'Model')+' · '+esc([t.origin,t.destination].filter(Boolean).join(' → ')||t.destination||'Travel')+'</strong><span>'+fmtDate(t.starts_at)+' → '+fmtDate(t.ends_at)+' · '+esc(t.purpose||'Travel')+' · Owner '+esc(memberName(t.assigned_member_id))+'</span><div class="v1682-linked">'+seg.length+' itinerary segment(s) · '+house.length+' accommodation record(s)</div></div><div class="v1682-row-actions">'+status(t.status)+'<button class="v1682-btn small" onclick="VEUX_MOBILITY_1682.addSegment(\''+t.id+'\')">+ Segment</button><button class="v1682-btn small" onclick="VEUX_MOBILITY_1682.addHousing(\''+t.id+'\')">+ Stay</button><button class="v1682-btn small" onclick="VEUX_MOBILITY_1682.editTravel(\''+t.id+'\')">Edit</button></div></div>';}
