function passportRow(p){return '<div class="v1682-row"><div><strong>'+esc(p.models&&p.models.display_name||'Model')+' · '+esc(p.country_code||'')+' Passport</strong><span>Expires '+fmtDate(p.expires_on)+' · '+esc(p.passport_number_masked||'Number not stored')+'</span></div><div class="v1682-row-actions">'+status(p.status)+'<button class="v1682-btn small" onclick="VEUX_MOBILITY_1682.editPassport(\''+p.id+'\')">Edit</button></div></div>';}
