function closeDetail(){var s=ensureShell();s.ov.classList.remove('on');s.dr.classList.remove('on');}
function getEvent(id){try{return (typeof loadCal==='function'?loadCal():[]).find(function(x){return String(x.id)===String(id);})||null;}catch(e){return null;}}
