 var s=ensureShell();
 var type=ev.type||ev.category||'Calendar Event',status=ev.status||ev.taskStatus||'Scheduled';
 var client=ev.client||'',contact=ev.cd||ev.castingDirector||ev.contact||'',models=modelNames(ev);
 var loc=ev.loc||ev.location||ev.address||'',market=ev.market||ev.country||'';
 var rate=[ev.rate,ev.rateType].filter(Boolean).join(' · '),usage=ev.usageTerms||ev.usageType||'';
 var creative=[ev.photographer&&('Photographer: '+ev.photographer),ev.castingDirector&&('Casting Director: '+ev.castingDirector),ev.stylist&&('Stylist: '+ev.stylist),ev.makeupArtist&&('MUA: '+ev.makeupArtist),ev.hairStylist&&('Hair: '+ev.hairStylist),ev.producer&&('Producer: '+ev.producer)].filter(Boolean).join('\n');
 s.dr.innerHTML='<div class="v1410-cal-head"><button class="v1410-cal-close" onclick="VEUX_V1410.close()">×</button><div class="v1410-cal-eye">'+E(type)+' · Calendar Detail</div><h2 class="v1410-cal-title">'+E(ev.title||'Untitled Event')+'</h2></div>'+
 '<div class="v1410-cal-body"><span class="v1410-cal-status">'+E(status)+'</span><div class="v1410-cal-grid">'+
 field('Date',ev.date)+field('Time',[ev.time,ev.endTime].filter(Boolean).join(' – '))+field('Model(s)',models)+field('Client / Brand',client)+field('Location',loc)+field('Market',market)+field('Contact',contact)+field('Rate',rate)+field('Usage',usage)+field('Pipeline',ev.pipelineStage)+
 '</div>'+section('Notes',ev.notes)+section('Creative Team',creative)+section('Travel / Logistics',ev.transportNotes)+section('Casting Brief',ev.castingBrief||ev.lookRequirements)+'</div>'+
 '<div class="v1410-cal-actions"><button onclick="VEUX_V1410.close()">Close</button><button class="primary" onclick="VEUX_V1410.edit(\''+E(String(ev.id)).replace(/&#39;/g,"\\'")+'\')">Edit '+E(type)+'</button><button onclick="VEUX_V1410.duplicate(\''+E(String(ev.id)).replace(/&#39;/g,"\\'")+'\')">Duplicate</button><button onclick="VEUX_V1410.openTask(\''+E(String(ev.id)).replace(/&#39;/g,"\\'")+'\')">Related Tasks</button></div>';
 requestAnimationFrame(function(){s.ov.classList.add('on');s.dr.classList.add('on');});
