if(typeof window.openEvent==='function'&&!window.__v1410_originalOpenEvent){window.__v1410_originalOpenEvent=window.openEvent;window.openEvent=function(id){if(id===null||id===undefined||id==='')return window.__v1410_originalOpenEvent(id);return showDetail(id);};}

